        _volume = 0;
        _accum = 0;
        _accumCycles = 0;
        _cyclesPerSample = (float)cyclesPerSec / sampleRate;
        _leftoverCycles = 0f;
        _lowpassBuf = 0f;
        _highpassBuf = 0f;
        _speed = sampleRate;
        _noiseLfsr = 0;
        _noiseLfsr0Old = 0;

