using ViceSharp.Core;
using Xunit;

/// <summary>
/// FR-VIC20-CPU-001 / AC-CPU-03 / TEST-VIC20-CPU-03: non-idle short workload lockstep.
/// Use case: after READY-stable boot, poke a deterministic busy INC/JMP loop into
/// both machines' RAM and prove every-cycle A/X/Y/S/P/PC match for a focused budget.
/// Acceptance: matchedCycles == budget.
/// </summary>
[Collection("NativeVice")]
public sealed class Vic20WorkloadLockstep
{
    /// <summary>~0.1s PAL after boot; stays in default Vic20 filter.</summary>
    public const int WorkloadBudget = 100_000;

    public const int BootCycles = 200_000;

    [Fact]
    public void EveryCycle_Workload_IncLoop_Match_FocusedPal()
    {
        if (!ViceNativeXvic.IsAvailable)
            return;

        var matched = RunWorkload(WorkloadBudget, "vic20");
        Assert.Equal(WorkloadBudget, matched);
    }

    [Fact]
    public void EveryCycle_Workload_IncLoop_Match_FocusedNtsc()
    {
        if (!ViceNativeXvic.IsAvailable)
            return;

        var matched = RunWorkload(WorkloadBudget, "vic20ntsc");
        Assert.Equal(WorkloadBudget, matched);
    }

    /// <summary>
    /// Boot both machines, inject zero-page INC loop at $033C (cassette buffer),
    /// set PC to $033C on both via successive steps until aligned, then lockstep.
    /// Uses bus writes only (no invent opcodes beyond 6502 INC zp / JMP abs).
    /// </summary>
    public static int RunWorkload(int budget, string model)
    {
        using var native = ViceNative.CreateInstance(model);
        native.Reset();
        var managed = MachineTestFactory.CreateVic20Machine(model);
        managed.Reset();

        for (var i = 0; i < BootCycles; i++)
        {
            native.Step();
            managed.Clock.Step();
        }

        // Cassette buffer $033C: INC $00; JMP $033C  => E6 00 4C 3C 03
        ReadOnlySpan<byte> prog = [0xE6, 0x00, 0x4C, 0x3C, 0x03];
        for (var i = 0; i < prog.Length; i++)
        {
            var addr = (ushort)(0x033C + i);
            native.WriteBus(addr, prog[i]);
            managed.Bus.Write(addr, prog[i]);
        }

        // Force PC by writing vectors is wrong; instead fill stack return and
        // use a soft JMP by writing KERNAL warm path is heavy. Simpler: set
        // PC through repeated compare of PC after JSR is unavailable.
        // Soft approach: overwrite the next IRQ/NMI is fragile. Use CPU soft
        // state via equal step until both PCs leave READY, then write
        // instruction stream under current PC (same PC after lockstep boot).
        var pc = native.GetCpuState().Pc;
        Assert.Equal(pc, managed.Devices.GetAll<ViceSharp.Chips.Cpu.Mos6502>().First().Pc);

        // Install JMP $033C over current PC so both enter the loop next fetch.
        native.WriteBus(pc, 0x4C);
        native.WriteBus((ushort)(pc + 1), 0x3C);
        native.WriteBus((ushort)(pc + 2), 0x03);
        managed.Bus.Write(pc, 0x4C);
        managed.Bus.Write((ushort)(pc + 1), 0x3C);
        managed.Bus.Write((ushort)(pc + 2), 0x03);

        return Vic20DivergeProbe.RunEveryCycleFromLive(native, managed, budget);
    }
}
