        ReadOnlySpan<byte> prog = [0xE6, 0x00, 0x4C, 0x3C, 0x03];
        for (var i = 0; i < prog.Length; i++)
        {
            var addr = (ushort)(0x033C + i);
            native.WriteBus(addr, prog[i]);
            managed.Bus.Write(addr, prog[i]);
        }

        var nPc = native.GetState().PC;
        var mPc = managed.GetState().PC;
        Assert.Equal(nPc, mPc);

        // JMP abs $033C under current PC so both enter the loop.
        native.WriteBus(nPc, 0x4C);
        native.WriteBus((ushort)(nPc + 1), 0x3C);
        native.WriteBus((ushort)(nPc + 2), 0x03);
        managed.Bus.Write(mPc, 0x4C);
        managed.Bus.Write((ushort)(mPc + 1), 0x3C);
        managed.Bus.Write((ushort)(mPc + 2), 0x03);

        for (var i = 1; i <= budget; i++)
        {
            native.Step();
            managed.Clock.Step();
            AssertEqualCpu(native, managed, BootCycles + i);
        }

        return budget;
    }

    private static void AssertEqualCpu(IViceNative native, CoordinatorMachine managed, int cycle)
    {
        var n = native.GetState();
        var m = managed.GetState();
        if (n.PC == m.PC && n.A == m.A && n.X == m.X && n.Y == m.Y && n.S == m.S && n.P == m.P)
            return;
        throw new Xunit.Sdk.XunitException(
            $"WORKLOAD DIV c={cycle} nPC=${n.PC:X4} mPC=${m.PC:X4} " +
            $"nA=${n.A:X2} mA=${m.A:X2} nX=${n.X:X2} mX=${m.X:X2} " +
            $"nY=${n.Y:X2} mY=${m.Y:X2} nS=${n.S:X2} mS=${m.S:X2} nP=${n.P:X2} mP=${m.P:X2}");
    }
}
