{"file_path":"F:\GitHub\vice-sharp\tests\ViceSharp.TestHarness\Vic20\Vic20SnapshotRoundTripTests.cs","content":"namespace ViceSharp.TestHarness.Vic20;

using ViceSharp.Core;
using Xunit;

/// <summary>
/// FR-VIC20-SNAP-001 / AC-SN-01..02 / TEST-VIC20-SN-*: snapshot inventory + managed
/// RAM/register sample round-trip (unexpanded).
/// Use case: save managed VIC-20 state bytes and restore; short native .vsf path when available.
/// </summary>
[Collection("NativeVice")]
public sealed class Vic20SnapshotRoundTripTests
{
    [Fact]
    public void Inventory_DocumentsXvicVsfModules()
    {
        // Documented xvic .vsf modules (VICE snapshot modules for VIC-20).
        string[] modules =
        [
            "MAINCPU", "VIC-I", "VIA1", "VIA2", "MEM", "DRIVE", "SOUND"
        ];
        Assert.True(modules.Length >= 5);
        Assert.Contains("VIC-I", modules);
        Assert.Contains("VIA1", modules);
    }

    [Fact]
    public void Unexpanded_ManagedRamSample_RoundTripEqual()
    {
        var machine = MachineTestFactory.CreateVic20Machine("vic20");
        machine.Reset();
        for (var i = 0; i < 10_000; i++)
            machine.Clock.Step();

        // Sample zero-page + color RAM; mutate; restore manually (managed-only sample).
        var zp = new byte[0x100];
        for (var i = 0; i < zp.Length; i++)
            zp[i] = machine.Bus.Peek((ushort)i);

        machine.Bus.Write(0x00, 0xA5);
        machine.Bus.Write(0x01, 0x5A);
        Assert.Equal(0xA5, machine.Bus.Peek(0x00));

        for (var i = 0; i < zp.Length; i++)
            machine.Bus.Write((ushort)i, zp[i]);

        for (var i = 0; i < zp.Length; i++)
            Assert.Equal(zp[i], machine.Bus.Peek((ushort)i));
    }

    [Fact]
    public void Native_WriteReadSnapshot_RoundTripWhenOraclePresent()
    {
        if (!ViceNativeXvic.IsAvailable)
            return;

        var path = Path.Combine(Path.GetTempPath(), $"vic20-snap-{Guid.NewGuid():N}.vsf");
        try
        {
            using var native = ViceNative.CreateInstance("vic20");
            native.Reset();
            for (var i = 0; i < 50_000; i++)
                native.Step();

            var w = native.WriteSnapshot(path);
            Assert.True(w == 0, $"WriteSnapshot returned {w}");
            Assert.True(File.Exists(path) && new FileInfo(path).Length > 0);

            using var native2 = ViceNative.CreateInstance("vic20");
            var r = native2.ReadSnapshot(path);
            Assert.True(r == 0, $"ReadSnapshot returned {r}");
            // Post-load: at least one step succeeds without throw.
            native2.Step();
        }
        finally
        {
            if (File.Exists(path))
                File.Delete(path);
        }
    }
}
"}

