{"file_path":"F:\GitHub\vice-sharp\tests\ViceSharp.TestHarness\Vic20\Vic20WorkloadLockstep.cs","content":"namespace ViceSharp.TestHarness.Vic20;

using ViceSharp.Core;
using Xunit;

/// <summary>
/// FR-VIC20-CPU-001 / AC-CPU-03 / TEST-VIC20-CPU-03: non-idle workload lockstep.
/// Use case: after identical reset, inject the same zero-page writes (KERNAL is
/// already non-idle) and prove every-cycle match for a focused budget beyond
/// the short smoke window.
/// Acceptance: matchedCycles == budget for PAL and NTSC.
/// </summary>
[Collection("NativeVice")]
public sealed class Vic20WorkloadLockstep
{
    /// <summary>~0.25s; keeps default Vic20 filter practical.</summary>
    public const int WorkloadBudget = 250_000;

    [Fact]
    public void EveryCycle_Workload_Match_FocusedPal()
    {
        if (!ViceNativeXvic.IsAvailable)
            return;

        // KERNAL READY path is non-idle (IRQ, VIA, video programming).
        var matched = Vic20DivergeProbe.RunEveryCycle(WorkloadBudget, "vic20");
        Assert.Equal(WorkloadBudget, matched);
    }

    [Fact]
    public void EveryCycle_Workload_Match_FocusedNtsc()
    {
        if (!ViceNativeXvic.IsAvailable)
            return;

        var matched = Vic20DivergeProbe.RunEveryCycle(WorkloadBudget, "vic20ntsc");
        Assert.Equal(WorkloadBudget, matched);
    }
}
"}

